sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        // Get the name of the person the reservation was for
        var reservedFor = inputs.reserved_for
            ? inputs.reserved_for.getValue('name')
            : 'Unknown';

        // Get the workspace name
        var workspace = inputs.workspace
            ? inputs.workspace.getValue('workspace_name')
            : 'Unknown';

        // Rejection message: no date, no tracker link —
        // rejected requests never create a tracker record
        var message = 'Workspace reservation rejected for ' + reservedFor +
            ' - ' + workspace;

        var discord = new discordNotification();
        discord.sendMessage(message, '\u274C');

    } catch (ex) {
        gs.error('Discord rejection error: ' + ex.message);
    }
})(inputs, outputs);

